{
  "cards": [
    {
      "advanced_exceptions": [],
      "context_id": "",
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Name: Ambessa. Official role tags: Fighter, Assassin.",
              "source_id": "riot:role"
            }
          ],
          "id": "overview_role",
          "summary": "Ambessa is a fighter and assassin."
        },
        {
          "citations": [
            {
              "quote": "Medarda Maxim: Ambessa's next basic attack gains range, bonus attack speed, deals bonus physical damage, and restores energy.",
              "source_id": "wiki:drakehoundsstep"
            },
            {
              "quote": "Active: Ambessa slashes with her twin drakehounds in the target direction, dealing physical damage to enemies hit.",
              "source_id": "wiki:cunningsweep"
            },
            {
              "quote": "After Ambessa finishes bracing, she smashes the ground beneath her, dealing physical damage to nearby enemies.",
              "source_id": "wiki:repudiation"
            },
            {
              "quote": "Active: Ambessa spins her twin drakehounds around her, dealing physical damage to enemies hit and slowing them briefly.",
              "source_id": "wiki:lacerate"
            }
          ],
          "id": "overview_damage",
          "summary": "Her fighting pattern combines physical ability damage with empowered attacks that restore energy."
        },
        {
          "citations": [
            {
              "quote": "Entering an attack or movement command while casting an ability will cause Ambessa to dash a short distance once the ability is cast",
              "source_id": "riot:P"
            },
            {
              "quote": "This dash cannot pass through terrain.Ambessa cannot dash while immobilized or grounded.",
              "source_id": "wiki:drakehoundsstep"
            },
            {
              "quote": "Ambessa blinks to the farthest enemy champion in a line of her choosing and suppresses them upon her arrival.",
              "source_id": "riot:R"
            }
          ],
          "id": "overview_mobility",
          "summary": "Ability-linked dashes support repeated repositioning, but cannot cross terrain or occur while immobilized or grounded; her ultimate provides a targeted blink."
        }
      ],
      "kind": "overview",
      "purpose": "Recognize her physical pressure, attack weaving, and mobility limits before judging an engagement.",
      "slot": "",
      "source_ids": ["riot:role", "riot:P", "riot:R", "wiki:drakehoundsstep", "wiki:cunningsweep", "wiki:repudiation", "wiki:lacerate"],
      "subject_id": "riot:role",
      "title": "Ambessa: fighting pattern",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [],
      "context_id": "",
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "During the lockout of Ambessa's abilities, inputting an attack or movement command causes her to dash to or towards the target or location, respectively, after the lockout ends.",
              "source_id": "wiki:drakehoundsstep"
            },
            {
              "quote": "This dash cannot pass through terrain.Ambessa cannot dash while immobilized or grounded.",
              "source_id": "wiki:drakehoundsstep"
            }
          ],
          "id": "step_trigger_limits",
          "summary": "Attack or movement commands during ability lockouts trigger a subsequent dash toward the target or location; terrain, immobilization, and grounding limit it."
        },
        {
          "citations": [
            {
              "quote": "Casting an ability generates a stack of Medarda Maxim for a few seconds, up to 3 stacks. Basic attacks consume one stack to become empowered.",
              "source_id": "wiki:drakehoundsstep"
            },
            {
              "quote": "Medarda Maxim: Ambessa's next basic attack gains range, bonus attack speed, deals bonus physical damage, and restores energy.",
              "source_id": "wiki:drakehoundsstep"
            }
          ],
          "id": "step_energy_cycle",
          "summary": "Ability casts build up to 3 Medarda Maxim stacks; basic attacks consume one stack for added range, attack speed, physical damage, and energy restoration."
        },
        {
          "citations": [
            {
              "quote": "During Drakehound's Step, a visual indicator is visible to Ambessa displaying the eventual dash's direction and destination location.",
              "source_id": "wiki:drakehoundsstep"
            },
            {
              "quote": "The number of available attacks empowered by Medarda Maxim are visible as pips under Ambessa's health bar, only visible to the player.",
              "source_id": "wiki:drakehoundsstep"
            }
          ],
          "id": "step_private_indicators",
          "summary": "Dash destination indicators and empowered-attack pips are private information visible to Ambessa's player."
        }
      ],
      "kind": "system",
      "purpose": "Anticipate repositioning after casts and recognize why attack access sustains her energy cycle.",
      "slot": "P",
      "source_ids": ["riot:P", "wiki:drakehoundsstep"],
      "subject_id": "wiki:drakehoundsstep",
      "title": "Drakehound's Step and energy cycle",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [],
      "context_id": "",
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Active: Ambessa slashes with her twin drakehounds in the target direction, dealing physical damage to enemies hit. The damage is increased against enemies hit by the outer edge.",
              "source_id": "wiki:cunningsweep"
            }
          ],
          "id": "sweep_edge",
          "summary": "The directional slash deals physical damage, with increased damage at its outer edge."
        },
        {
          "citations": [
            {
              "quote": "If this hits at least one enemy, Ambessa can cast Sundering Slam within the next few seconds.",
              "source_id": "wiki:cunningsweep"
            }
          ],
          "id": "sweep_unlock",
          "summary": "Hitting an enemy temporarily unlocks Sundering Slam."
        }
      ],
      "kind": "ability",
      "purpose": "Recognize the outer-edge threat and track whether a hit enabled the follow-up.",
      "slot": "Q",
      "source_ids": ["riot:Q", "wiki:cunningsweep"],
      "subject_id": "wiki:cunningsweep",
      "title": "Cunning Sweep",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [],
      "context_id": "wiki:cunningsweep",
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Active: Ambessa slams her twin drakehounds in a line in the target direction, dealing physical damage to enemies hit. The damage is increased against the first enemy.",
              "source_id": "wiki:sunderingslam"
            }
          ],
          "id": "slam_line_priority",
          "summary": "The follow-up is a line slam dealing physical damage, with increased damage against the first enemy hit."
        }
      ],
      "kind": "ability_variant",
      "purpose": "Recognize the line-shaped follow-up and its increased threat to the first target.",
      "slot": "Q",
      "source_ids": ["riot:Q", "wiki:cunningsweep", "wiki:sunderingslam"],
      "subject_id": "wiki:sunderingslam",
      "title": "Sundering Slam",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Ambessa will smash the ground at the end of Drakehound's Step's dash if she would finish bracing during it, and otherwise always smashes the ground from wherever she is at the end of the bracing time.",
              "source_id": "wiki:repudiation"
            }
          ],
          "status": "supported",
          "summary": "The smash's precise timing depends on whether bracing finishes during the dash; otherwise it occurs at her position when bracing ends."
        }
      ],
      "context_id": "",
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Ambessa gains a shield, briefly braces herself, and then slams the ground to damage nearby enemies.",
              "source_id": "riot:W"
            }
          ],
          "id": "repudiation_shield_smash",
          "summary": "Ambessa shields herself and braces before damaging nearby enemies with a ground smash."
        },
        {
          "citations": [
            {
              "quote": "If the shield absorbs damage from a champion, large monster or turret during her bracing, the smash's damage is increased.",
              "source_id": "wiki:repudiation"
            }
          ],
          "id": "repudiation_empower",
          "summary": "Shield absorption of champion, large-monster, or turret damage during bracing increases the smash's damage."
        },
        {
          "citations": [
            {
              "quote": "If she performs Drakehound's Step's dash during Repudiation, she will smash the ground at her destination instead.",
              "source_id": "wiki:repudiation"
            }
          ],
          "id": "repudiation_reposition",
          "summary": "Drakehound's Step can reposition the ground smash to her dash destination."
        }
      ],
      "kind": "ability",
      "purpose": "Recognize the shielded retaliation window and anticipate the smash moving with her dash.",
      "slot": "W",
      "source_ids": ["riot:W", "wiki:repudiation"],
      "subject_id": "wiki:repudiation",
      "title": "Repudiation",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "She will spin a second time even if the dash is interrupted.",
              "source_id": "wiki:lacerate"
            }
          ],
          "status": "supported",
          "summary": "Interrupting the dash does not prevent the second spin."
        }
      ],
      "context_id": "",
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Active: Ambessa spins her twin drakehounds around her, dealing physical damage to enemies hit and slowing them briefly.",
              "source_id": "wiki:lacerate"
            }
          ],
          "id": "lacerate_spin_slow",
          "summary": "A surrounding spin deals physical damage and briefly slows enemies hit."
        },
        {
          "citations": [
            {
              "quote": "If Ambessa performs Drakehound's Step's dash after the spin, she will spin a second time upon arrival to apply the same effects.",
              "source_id": "wiki:lacerate"
            }
          ],
          "id": "lacerate_dash_repeat",
          "summary": "Dashing with Drakehound's Step after the spin produces a second spin on arrival, repeating its damage and slow."
        }
      ],
      "kind": "ability",
      "purpose": "Anticipate the repeated area threat at her dash endpoint.",
      "slot": "E",
      "source_ids": ["riot:E", "wiki:lacerate"],
      "subject_id": "wiki:lacerate",
      "title": "Lacerate",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "If the target resists the suppression by being immune to crowd control, displacement immune, or having a spell shield, Ambessa will not attach them to herself.",
              "source_id": "wiki:publicexecution"
            },
            {
              "quote": "She will be unable to apply the damage and stun in this case since the suppression was not applied in the first place.\nShe will still blink to the target in this case.",
              "source_id": "wiki:publicexecution"
            },
            {
              "quote": "If the target removes the suppression by any means, including with an applicable cleanse effect or dispel, they will instantly detach themselves from Ambessa, which causes the ability to cancel immediately.",
              "source_id": "wiki:publicexecution"
            }
          ],
          "status": "supported",
          "summary": "Preventing suppression leaves the blink intact but prevents attachment, damage, and stun. Removing suppression early detaches the target and cancels the ability."
        }
      ],
      "context_id": "",
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Passive: Ambessa gains armor penetration and heals for a percentage of the damage dealt by her active abilities.",
              "source_id": "wiki:publicexecution"
            }
          ],
          "id": "execution_passive",
          "summary": "The ultimate's passive grants armor penetration and healing from active-ability damage."
        },
        {
          "citations": [
            {
              "quote": "Active: Ambessa prepares a strike in a line in the target direction, then blinks behind the farthest enemy champion within the area and seizes them.",
              "source_id": "wiki:publicexecution"
            },
            {
              "quote": "Ambessa blinks to the farthest enemy champion in a line of her choosing and suppresses them upon her arrival. She then slams the enemy into the ground where they take damage and are stunned.",
              "source_id": "riot:R"
            }
          ],
          "id": "execution_target_control",
          "summary": "After preparing a line strike, Ambessa blinks behind the farthest enemy champion in its area, suppresses them, and slams them for damage and a stun."
        },
        {
          "citations": [
            {
              "quote": "Ambessa is displacement immune and unable to act during the cast time and while the target is suppressed.",
              "source_id": "wiki:publicexecution"
            }
          ],
          "id": "execution_immunity",
          "summary": "During preparation and the target's suppression, Ambessa is displacement immune and unable to act."
        }
      ],
      "kind": "ability",
      "purpose": "Recognize farthest-target selection, the suppression sequence, and the passive source of penetration and sustain.",
      "slot": "R",
      "source_ids": ["riot:R", "wiki:publicexecution"],
      "subject_id": "wiki:publicexecution",
      "title": "Public Execution",
      "unsupported_claims": []
    }
  ],
  "conflicts": [
    {
      "resolution": "Use the wiki's explicit champion, large-monster, and turret trigger list for the learning core; Riot's 'non-minion damage' wording is broader and does not establish every possible damage source.",
      "source_ids": ["riot:W", "wiki:repudiation"],
      "topic": "Repudiation empowerment trigger scope"
    },
    {
      "resolution": "Teach that the dash can reposition the smash. Preserve the detailed bracing-versus-dash timing as an advanced qualification to the abbreviated destination description.",
      "source_ids": ["wiki:repudiation", "riot:W"],
      "topic": "Repudiation smash location and timing"
    }
  ],
  "factual_risks": [
    "The supplied Data Dragon release is pinned; its numbering does not establish a current game patch.",
    "Bug and unexpected-behavior annotations are excluded from established cores, including passive on-hit consumption, shield display delay, ultimate immunity lingering, direction-change bugs, and Flash queuing.",
    "Raw interaction tables and duplicated wiki passages are not independently verified mechanics.",
    "No supplied evidence establishes unusual skill leveling, a separate weapon system, or main-hand/off-hand interactions."
  ],
  "features": ["standard", "resource_cycle", "ability_variants", "conditional_effects"],
  "relationships": [
    {
