      "citations": [
        {
          "quote": "Striking an enemy will transform the next cast of this ability for a short period of time, causing her to slam her twin drakehounds down in a line in front of her",
          "source_id": "riot:Q"
        }
      ],
      "condition": "Temporarily available after Cunning Sweep connects.",
      "from_id": "wiki:sunderingslam",
      "kind": "variant_of",
      "to_id": "wiki:cunningsweep"
    },
    {
      "citations": [
        {
          "quote": "If she performs Drakehound's Step's dash during Repudiation, she will smash the ground at her destination instead.",
          "source_id": "wiki:repudiation"
        }
      ],
      "condition": "Drakehound's Step is performed during Repudiation; precise timing follows the bracing interaction.",
      "from_id": "wiki:drakehoundsstep",
      "kind": "conditional_effect",
      "to_id": "wiki:repudiation"
    },
    {
      "citations": [
        {
          "quote": "Initiating Drakehound's Step from this ability causes her to strike a second time at the end of its dash.",
          "source_id": "riot:E"
        }
      ],
      "condition": "Drakehound's Step is initiated from Lacerate.",
      "from_id": "wiki:drakehoundsstep",
      "kind": "conditional_effect",
      "to_id": "wiki:lacerate"
    }
  ],
  "section_disposition": [
    {
      "disposition": "taught",
      "reason": "A system card explains dash access, empowered attacks, and energy restoration; private UI indicators are merged into that explanation.",
      "source_id": "wiki:drakehoundsstep",
      "target_subject_ids": ["wiki:drakehoundsstep", "riot:role"]
    },
    {
      "disposition": "taught",
      "reason": "The outer-edge damage pattern and hit-dependent follow-up unlock are distinct recognition goals.",
      "source_id": "wiki:cunningsweep",
      "target_subject_ids": ["wiki:cunningsweep"]
    },
    {
      "disposition": "taught",
      "reason": "The unlocked line attack has a different shape and target-priority damage pattern, warranting a contextual variant card.",
      "source_id": "wiki:sunderingslam",
      "target_subject_ids": ["wiki:sunderingslam"]
    },
    {
      "disposition": "taught",
      "reason": "Shielded bracing, damage-triggered empowerment, and dash relocation form a useful retaliation-recognition goal; precise timing stays advanced.",
      "source_id": "wiki:repudiation",
      "target_subject_ids": ["wiki:repudiation"]
    },
    {
      "disposition": "taught",
      "reason": "The nearby slow and dash-triggered repeat are a distinct area-threat recognition goal.",
      "source_id": "wiki:lacerate",
      "target_subject_ids": ["wiki:lacerate"]
    },
    {
      "disposition": "taught",
      "reason": "Target selection, suppression sequence, passive sustain, and displacement immunity fit together; suppression-failure interactions stay advanced.",
      "source_id": "wiki:publicexecution",
      "target_subject_ids": ["wiki:publicexecution"]
    }
  ],
